def read_batches(values, batch_size):
    if batch_size <= 0:
        raise ValueError("batch_size must be positive")
    for start in range(0, len(values), batch_size):
        yield values[start:start + batch_size]

for batch in read_batches(list(range(10)), 4):
    print(batch)

def make_batches(data, batch_size):
    if batch_size <= 0:
        raise ValueError("batch_size must be positive")
    if data is None:
        raise TypeError("data must not be None")

    return [
        data[i:i + batch_size]
        for i in range(0, len(data), batch_size)
    ]

print(make_batches([1, 2, 3, 4, 5], 2))

def normalize_score(score: float, maximum: float) -> float:
    if maximum <= 0:
        raise ValueError("maximum must be positive")
    return score / maximum

import math

def parse_measurement(raw):
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return None

    if not math.isfinite(value):
        return None
    return value

print(parse_measurement("3.14"))
print(parse_measurement("unknown"))
print(parse_measurement(float("nan")))

def min_max_scale(values):
    if not values:
        raise ValueError("values must not be empty")
    low, high = min(values), max(values)
    if low == high:
        return [0.0 for _ in values]
    return [(x - low) / (high - low) for x in values]

assert min_max_scale([2, 4, 6]) == [0.0, 0.5, 1.0]
assert min_max_scale([5, 5]) == [0.0, 0.0]

