import json
import math

def clean_numbers(raw_values):
    cleaned = []
    for raw in raw_values:
        try:
            value = float(raw)
        except (TypeError, ValueError):
            continue
        if math.isfinite(value):
            cleaned.append(value)
    return cleaned

raw = ["1.2", "2.5", "missing", None, "4.0"]
values = clean_numbers(raw)
if not values:
    raise ValueError("no valid measurements")

summary = {
    "count": len(values),
    "mean": sum(values) / len(values),
    "values": values
}
print(json.dumps(summary, indent=2))
